src/integrations/riscv_cpu/recursive_seg:
//! Four-leaf real SegmentV2 fixture used by the multi-level recursion gate.
//! Keeping this transaction separate prevents the single-leaf proof authority
//! from becoming a second integration facade.

const std = @import("std");
const frontend = @import("stwo_riscv_frontend");
const integration = @import("stwo_riscv_cpu_integration");

const ingress = @import("recursive_segment_v2_leaf_outer_proof_test.zig");
const subject = integration.recursive_segment_v2_leaf_outer;
const runner = frontend.runner;
const recursion = frontend.recursion;
const span = recursion.span_statement;
const protocol = recursion.protocol;

/// Four adjacent independently verified SegmentV2 leaves. Every leaf crosses
/// prove/serialize/preflight/decode/fresh-verify custody before the hook can
/// observe the fixed array.
pub fn runTemporalQuadGateWithHook(
    allocator: std.mem.Allocator,
    comptime Hook: type,
) !void {
    comptime {
        if (!@hasDecl(Hook, "run"))
            @compileError("temporal V2 quad hook must declare run");
        @import("stwo_prover_api").assertProverEngine(subject.Engine);
    }

    const elf = frontend.testing.guest_precompile_test_elf.buildTemporalQuad();
    var session = try runner.Poseidon2ExecutionSession.init(allocator, &elf, .{});
    defer session.deinit();
    var profile0 = try session.startSegment(1);
    defer profile0.deinit();
    var profile1 = try session.resumeSegment(profile0.base.continuation.?, 1);
    defer profile1.deinit();
    var profile2 = try session.resumeSegment(profile1.base.continuation.?, 1);
    defer profile2.deinit();
    var profile3 = try session.resumeSegment(profile2.base.continuation.?, 16);
    defer profile3.deinit();
    const results = [4]*const runner.SegmentResult{
        &profile0.base,
        &profile1.base,
        &profile2.base,
        &profile3.base,
    };

    var declared_program = try frontend.air.program.commitment.buildDeclared(
        allocator,
        results[0].execution_trace.rows.items,
        results[0].rw_memory.program_words,
        null,
    );
    defer declared_program.deinit(allocator);
    const public_input = ingress.digest("recursive-v2-quad-input");
    const public_output = ingress.digest("recursive-v2-quad-output");
    const states = [5]span.MachineState{
        try ingress.machineState(
            results[0].entry_cpu,
            recursion.segment_statement_v2.snapshotDigest(results[0].rw_memory.words, .initial_word).id,
            ingress.digest("recursive-v2-quad-io-entry"),
        ),
        try ingress.machineState(
            results[0].exit_cpu,
            recursion.segment_statement_v2.snapshotDigest(results[0].rw_memory.words, .final_word).id,
            ingress.digest("recursive-v2-quad-io-1"),
        ),
        try ingress.machineState(
            results[1].exit_cpu,
            recursion.segment_statement_v2.snapshotDigest(results[1].rw_memory.words, .final_word).id,
            ingress.digest("recursive-v2-quad-io-2"),
        ),
        try ingress.machineState(
            results[2].exit_cpu,
            recursion.segment_statement_v2.snapshotDigest(results[2].rw_memory.words, .final_word).id,
            ingress.digest("recursive-v2-quad-io-3"),
        ),
        try ingress.machineState(
            results[3].exit_cpu,
            recursion.segment_statement_v2.snapshotDigest(results[3].rw_memory.words, .final_word).id,
            ingress.digest("recursive-v2-quad-io-exit"),
        ),
    };
    const entry_states = [3]span.MachineState{
        try ingress.machineState(
            results[1].entry_cpu,
            recursion.segment_statement_v2.snapshotDigest(results[1].rw_memory.words, .initial_word).id,
            ingress.digest("recursive-v2-quad-io-1"),
        ),
        try ingress.machineState(
            results[2].entry_cpu,
            recursion.segment_statement_v2.snapshotDigest(results[2].rw_memory.words, .initial_word).id,
            ingress.digest("recursive-v2-quad-io-2"),
        ),
        try ingress.machineState(
            results[3].entry_cpu,
            recursion.segment_statement_v2.snapshotDigest(results[3].rw_memory.words, .initial_word).id,
            ingress.digest("recursive-v2-quad-io-3"),
        ),
    };
    for (entry_states, states[1..4]) |entry, previous_exit|
        if (!std.meta.eql(entry, previous_exit))
            return error.InvalidTemporalBoundary;

    var total_cycles: u64 = 0;
    for (results) |result|
        total_cycles = try std.math.add(
            u64,
            total_cycles,
            @intCast(result.cycle_count),
        );
    const job = try span.JobContext.init(
        try span.CompleteExecution.init(
            protocol.PROTOCOL_ID_WORDS,
            ingress.scalarDigest(declared_program.tree.root),
            states[0],
            states[4],
            public_input,
            public_output,
            total_cycles,
        ),
        4,
    );
    const statements = [4]span.SpanStatement{
        try ingress.leafStatement(
            job,
            results[0],
            states[0],
            states[1],
            try span.EdgeClaim.present(public_input),
            span.EdgeClaim.absent(),
        ),
        try ingress.leafStatement(
            job,
            results[1],
            states[1],
            states[2],
            span.EdgeClaim.absent(),
            span.EdgeClaim.absent(),
        ),
        try ingress.leafStatement(
            job,
            results[2],
            states[2],
            states[3],
            span.EdgeClaim.absent(),
            span.EdgeClaim.absent(),
        ),
        try ingress.leafStatement(
            job,
            results[3],
            states[3],
            states[4],
            span.EdgeClaim.absent(),
            try span.EdgeClaim.present(public_output),
        ),
    };
    const keys = try recursion.segment_leaf_authority_v2.VerifierKeyAuthorityV2.init(
        ingress.digest("recursive-v2-segment-vk"),
        ingress.digest("recursive-v2-parent-vk"),
    );

    var prepared: [4]subject.PreparedNativeV2LeafOuter = undefined;
    var prepared_count: usize = 0;
    defer for (prepared[0..prepared_count]) |*leaf| leaf.deinit();
    for (&prepared, results, statements) |*destination, result, statement| {
        destination.* = try ingress.prepareTemporalNativeLeaf(
            allocator,
            result,
            statement,
            keys,
        );
        prepared_count += 1;
    }
    for (prepared, 0..) |left, left_index|
        for (prepared[left_index + 1 ..]) |right|
            if (std.mem.eql(u8, &left.identity, &right.identity))
                return error.DuplicateTemporalLeaf;
    try Hook.run(allocator, &prepared);
}

src/integrations/riscv_cpu/recursive_tem:
//! Real four-leaf temporal aggregation custody gate.
//!
//! Four distinct adjacent SegmentV2 leaves are independently proved and
//! verified.  Two independent temporal-parent STARKs are then proved and
//! verified, each minting the append-only binary-child sidecar.  Finally the
//! canonical height-2 cohort proves and independently verifies their root.

const std = @import("std");
const frontend = @import("stwo_riscv_frontend");
const integration = @import("stwo_riscv_cpu_integration");

const quad_fixture = @import("recursive_segment_v2_temporal_quad_fixture.zig");
const parent_gate = @import("recursive_temporal_parent_real_proof_test.zig");
const parent_capture = integration.recursive_temporal_verified_parent_capture_v1;

const leaf_outer = integration.recursive_segment_v2_leaf_outer;
const level2 = integration.recursive_temporal_parent_pair_authority_v1;
const level2_suffix = integration.recursive_temporal_level2_suffix_v1;
const verified_node = integration.recursive_temporal_verified_node_v1;
const recursion = frontend.recursion;

pub fn runGate(allocator: std.mem.Allocator) !void {
    return quad_fixture.runTemporalQuadGateWithHook(allocator, QuadHook);
}

const CapturedParent = parent_capture.VerifiedParentCaptureV1;

const QuadHook = struct {
    pub fn run(
        allocator: std.mem.Allocator,
        leaves: *const [4]leaf_outer.PreparedNativeV2LeafOuter,
    ) !void {
        var left_parent = CapturedParent.init(allocator);
        defer left_parent.deinit();
        try parent_gate.proveTemporalParentWithConsumer(
            allocator,
            &leaves[0],
            &leaves[1],
            &left_parent,
        );
        var right_parent = CapturedParent.init(allocator);
        defer right_parent.deinit();
        try parent_gate.proveTemporalParentWithConsumer(
            allocator,
            &leaves[2],
            &leaves[3],
            &right_parent,
        );

        const left_publication = &left_parent.publication.?;
        const left_artifact = &left_parent.artifact.?;
        const right_publication = &right_parent.publication.?;
        const right_artifact = &right_parent.artifact.?;
        var left_child: level2.PreparedParentChildV1 = undefined;
        level2.admitInto(
            &left_child,
            left_publication,
            left_artifact,
        ) catch |err| return stageFailure("left_parent_admission", err);
        var right_child: level2.PreparedParentChildV1 = undefined;
        level2.admitInto(
            &right_child,
            right_publication,
            right_artifact,
        ) catch |err| return stageFailure("right_parent_admission", err);
        const root_pin = recursion.temporal_pair_node.RootVkPinV2{
            .expected_aggregator_vk_id = left_artifact.child.recursive_parent_vk_id,
        };
        var root: level2.PreparedLevel2PairV1 = undefined;
        level2.prepareInto(
            &root,
            &left_child,
            &right_child,
            &root_pin,
        ) catch |err| return stageFailure("root_pair_prepare", err);
        const authenticated = try root.authenticatePrepared();
        try std.testing.expectEqual(
            level2.FIRST_MULTI_LEVEL_HEIGHT,
            authenticated.pair.parent_height,
        );
        try std.testing.expectEqual(
            @as(u64, 4),
            authenticated.pair.parent_statement.slots.capacity(),
        );
        const child_inputs = [2]level2_suffix.ChildInputV1{
            .{
                .publication = left_publication,
                .artifact = left_artifact,
                .capture = &left_parent.capture.?,
                .composition = &left_parent.composition.?,
            },
            .{
                .publication = right_publication,
                .artifact = right_artifact,
                .capture = &right_parent.capture.?,
                .composition = &right_parent.composition.?,
            },
        };
        var verified_root = verified_node.proveAndVerify(
            allocator,
            &root,
            child_inputs,
            .{},
        ) catch |err| return stageFailure("root_prove_verify", err);
        defer verified_root.deinit();
        try verified_root.validate();
        const root_receipt = verified_root.receipt;
        try std.testing.expect(root_receipt.canonical_proof_bytes > 0);
        try std.testing.expect(root_receipt.prove_ns > 0);
        try std.testing.expect(root_receipt.verify_ns > 0);
        try std.testing.expect(!std.mem.allEqual(
            u8,
            &root_receipt.canonical_proof_sha256,
            0,
        ));

        // Sibling order and parent-publication custody are protocol-visible.
        var untouched = root;
        try std.testing.expectError(
            error.ChildOrderMismatch,
            level2.prepareInto(
                &untouched,
                &right_child,
                &left_child,
                &root_pin,
            ),
        );
        var forged_artifact = left_artifact.*;
        forged_artifact.child.proof_id[0] +%= 1;
        try std.testing.expectError(
            error.ArtifactIdentityMismatch,
            level2.admitInto(
                &left_child,
                left_publication,
                &forged_artifact,
            ),
        );

        const total_parent_bytes = try std.math.add(
            usize,
            left_parent.receipt.?.canonical_proof_bytes,
            right_parent.receipt.?.canonical_proof_bytes,
        );
        const root_sha256_hex = std.fmt.bytesToHex(
            root_receipt.canonical_proof_sha256,
            .lower,
        );
        std.debug.print(
            "\nTEMPORAL_MULTILEVEL_REAL leaves=4 verified_parents=2 " ++
                "root_height={d} parent_bytes={d} root_bytes={d} " ++
                "root_prove_ms={d:.3} root_verify_ms={d:.3} " ++
                "root_sha256={s} root_proof={}\n",
            .{
                authenticated.pair.parent_height,
                total_parent_bytes,
                root_receipt.canonical_proof_bytes,
                milliseconds(root_receipt.prove_ns),
                milliseconds(root_receipt.verify_ns),
                &root_sha256_hex,
                true,
            },
        );
    }
};

fn milliseconds(nanoseconds: u64) f64 {
    return @as(f64, @floatFromInt(nanoseconds)) / std.time.ns_per_ms;
}

fn stageFailure(stage: []const u8, err: anyerror) anyerror {
    std.debug.print(
        "\nTEMPORAL_MULTILEVEL_STAGE_FAIL stage={s} error={s}\n",
        .{ stage, @errorName(err) },
    );
    if (@errorReturnTrace()) |trace| std.debug.dumpStackTrace(trace.*);
    return err;
}

test "real four-leaf temporal tree authenticates two verified parents" {
    try runGate(std.testing.allocator);
}

src/integrations/riscv_cpu/recursive_seg:
//! Eight-leaf real SegmentV2 fixture for the first generic recursion level.
//!
//! The fixture deliberately uses the existing all-family RV32 program instead
//! of introducing a recursion-specific guest. Seven one-cycle yields and one
//! terminal segment therefore exercise continuation custody while presenting
//! eight adjacent, independently verified leaves to the aggregation hook.

const std = @import("std");
const frontend = @import("stwo_riscv_frontend");
const integration = @import("stwo_riscv_cpu_integration");

const ingress = @import("recursive_segment_v2_leaf_outer_proof_test.zig");
const subject = integration.recursive_segment_v2_leaf_outer;
const runner = frontend.runner;
const recursion = frontend.recursion;
const span = recursion.span_statement;
const protocol = recursion.protocol;

pub const LEAF_COUNT: usize = 8;

/// Eight adjacent independently verified SegmentV2 leaves. Every leaf crosses
/// prove/serialize/preflight/decode/fresh-verify custody before publication.
pub fn runTemporalOctetGateWithHook(
    allocator: std.mem.Allocator,
    comptime Hook: type,
) !void {
    comptime {
        if (!@hasDecl(Hook, "run"))
            @compileError("temporal V2 octet hook must declare run");
        @import("stwo_prover_api").assertProverEngine(subject.Engine);
    }

    var elf = try buildTemporalOctetElf();
    var session = try runner.Poseidon2ExecutionSession.init(allocator, &elf, .{});
    defer session.deinit();

    var profiles: [LEAF_COUNT]runner.Poseidon2SegmentResult = undefined;
    var profile_count: usize = 0;
    defer for (profiles[0..profile_count]) |*profile| profile.deinit();
    profiles[0] = try session.startSegment(1);
    profile_count = 1;
    for (1..LEAF_COUNT) |index| {
        const continuation = profiles[index - 1].base.continuation orelse
            return error.MissingTemporalContinuation;
        profiles[index] = try session.resumeSegment(
            continuation,
            if (index + 1 == LEAF_COUNT) 64 else 1,
        );
        profile_count += 1;
    }
    if (!profiles[LEAF_COUNT - 1].base.isComplete())
        return error.IncompleteTemporalExecution;

    var results: [LEAF_COUNT]*const runner.SegmentResult = undefined;
    for (&results, &profiles) |*destination, *profile|
        destination.* = &profile.base;
    for (results) |result|
        if (result.cycle_count != 1)
            return error.NonUniformTemporalLeafGeometry;

    var declared_program = try frontend.air.program.commitment.buildDeclared(
        allocator,
        results[0].execution_trace.rows.items,
        results[0].rw_memory.program_words,
        null,
    );
    defer declared_program.deinit(allocator);

    const public_input = ingress.digest("recursive-v2-octet-input");
    const public_output = ingress.digest("recursive-v2-octet-output");
    var states: [LEAF_COUNT + 1]span.MachineState = undefined;
    states[0] = try ingress.machineState(
        results[0].entry_cpu,
        recursion.segment_statement_v2.snapshotDigest(results[0].rw_memory.words, .initial_word).id,
        publicIoDigest(0),
    );
    for (results, 0..) |result, index| {
        states[index + 1] = try ingress.machineState(
            result.exit_cpu,
            recursion.segment_statement_v2.snapshotDigest(result.rw_memory.words, .final_word).id,
            publicIoDigest(@intCast(index + 1)),
        );
        if (index != 0) {
            const entry = try ingress.machineState(
                result.entry_cpu,
                recursion.segment_statement_v2.snapshotDigest(result.rw_memory.words, .initial_word).id,
                publicIoDigest(@intCast(index)),
            );
            if (!std.meta.eql(entry, states[index]))
                return error.InvalidTemporalBoundary;
        }
    }

    var total_cycles: u64 = 0;
    for (results) |result|
        total_cycles = try std.math.add(
            u64,
            total_cycles,
            @intCast(result.cycle_count),
        );
    const job = try span.JobContext.init(
        try span.CompleteExecution.init(
            protocol.PROTOCOL_ID_WORDS,
            ingress.scalarDigest(declared_program.tree.root),
            states[0],
            states[LEAF_COUNT],
            public_input,
            public_output,
            total_cycles,
        ),
        LEAF_COUNT,
    );

    var statements: [LEAF_COUNT]span.SpanStatement = undefined;
    for (&statements, results, 0..) |*statement, result, index| {
        statement.* = try ingress.leafStatement(
            job,
            result,
            states[index],
            states[index + 1],
            if (index == 0)
                try span.EdgeClaim.present(public_input)
            else
                span.EdgeClaim.absent(),
            if (index + 1 == LEAF_COUNT)
                try span.EdgeClaim.present(public_output)
            else
                span.EdgeClaim.absent(),
        );
    }
    const keys = try recursion.segment_leaf_authority_v2.VerifierKeyAuthorityV2.init(
        ingress.digest("recursive-v2-segment-vk"),
        ingress.digest("recursive-v2-parent-vk"),
    );

    var prepared: [LEAF_COUNT]subject.PreparedNativeV2LeafOuter = undefined;
    var prepared_count: usize = 0;
    defer for (prepared[0..prepared_count]) |*leaf| leaf.deinit();
    for (&prepared, results, statements) |*destination, result, statement| {
        destination.* = try ingress.prepareTemporalNativeLeaf(
            allocator,
            result,
            statement,
            keys,
        );
        prepared_count += 1;
    }
    for (prepared, 0..) |left, left_index|
        for (prepared[left_index + 1 ..]) |right|
            if (std.mem.eql(u8, &left.identity, &right.identity))
                return error.DuplicateTemporalLeaf;
    try Hook.run(allocator, &prepared);
}

fn publicIoDigest(index: u32) span.Digest {
    return ingress.scalarDigest(0x4f43_0000 + index);
}

/// Derive an eight-instruction homogeneous program from the repository-owned
/// ELF builder without duplicating its private ELF layout. The source program
/// prefix is located and validated word-for-word before mutation; this keeps
/// the fixture robust to header/layout movement while ensuring every segment
/// has one identical LUI-family proof geometry.
fn buildTemporalOctetElf() ![frontend.testing.guest_precompile_test_elf.all_family_elf_size]u8 {
    const fixture = frontend.testing.guest_precompile_test_elf;
    var elf = fixture.buildAllFamilies();
    const offset = try findUniqueProgramOffset(
        &elf,
        &fixture.all_family_instructions,
    );
    const instructions = [_]u32{
        0x0010_00B7, // LUI x1, 0x100.
        0x0010_0137, // LUI x2, 0x100.
        0x0010_01B7, // LUI x3, 0x100.
        0x0010_0237, // LUI x4, 0x100.
        0x0010_02B7, // LUI x5, 0x100.
        0x0010_0337, // LUI x6, 0x100.
        0x0010_03B7, // LUI x7, 0x100.
        0x0010_0437, // LUI x8, 0x100.
        0x0000_006F, // JAL x0, 0: proof-bearing completion.
    };
    for (instructions, 0..) |instruction, index|
        std.mem.writeInt(
            u32,
            elf[offset + index * @sizeOf(u32) ..][0..@sizeOf(u32)],
            instruction,
            .little,
        );
    return elf;
}

fn findUniqueProgramOffset(elf: []const u8, instructions: []const u32) !usize {
    const byte_count = try std.math.mul(
        usize,
        instructions.len,
        @sizeOf(u32),
    );
    var found: ?usize = null;
    var offset: usize = 0;
    while (offset + byte_count <= elf.len) : (offset += @sizeOf(u32)) {
        var matches = true;
        for (instructions, 0..) |instruction, index| {
            const word_offset = offset + index * @sizeOf(u32);
            if (std.mem.readInt(
                u32,
                elf[word_offset..][0..@sizeOf(u32)],
                .little,
            ) != instruction) {
                matches = false;
                break;
            }
        }
        if (!matches) continue;
        if (found != null) return error.AmbiguousProgramImage;
        found = offset;
    }
    return found orelse error.ProgramImageNotFound;
}

//! One real-capture functional gate for the SegmentV2 non-core owner.
//!
//! This helper deliberately accepts the already prepared native leaf so the
//! shared ingress gate pays for native proving exactly once. It exercises no
//! outer STARK; the full proof belongs to the aggregate cohort gate.

const std = @import("std");
const stwo_core = @import("stwo_core");
const frontend = @import("stwo_riscv_frontend");
const integration = @import("stwo_riscv_cpu_integration");

const subject = integration.recursive_segment_v2_noncore_owner;
const core_outer = integration.recursive_fri_outer;
const leaf_outer = integration.recursive_segment_v2_leaf_outer;

const M31 = stwo_core.fields.m31.M31;
const recursion = frontend.recursion;
const manifest_mod = recursion.air.segment_outer_adapter_manifest_v2;
const universal = recursion.air.universal_challenges;
const shared_provider = recursion.air.universal_shared_provider;

pub const Error = error{
    CachedGenerationMismatch,
    CoreTreeMutation,
    ForeignContextAccepted,
    InteractionCacheMutation,
    RelationContextDidNotChange,
    TreePublicationEmpty,
};

pub fn runPrepared(
    allocator: std.mem.Allocator,
    prepared: *const leaf_outer.PreparedNativeV2LeafOuter,
) !void {
    try prepared.validate();
    const source_preflight = subject.PreflightV2.init(prepared) catch |err| {
        return failStage("preflight", err);
    };
    var changed_preflight = source_preflight;
    changed_preflight.transcript_prepared.source_id[0] ^= 1;
    try std.testing.expectError(error.SourceMismatch, changed_preflight.validateAgainst(prepared));
    changed_preflight = source_preflight;
    changed_preflight.input_provider_shape = try @TypeOf(changed_preflight.input_provider_shape).init(
        @as(usize, changed_preflight.input_provider_shape.claim_count) + 1,
    );
    try std.testing.expectError(error.SourceManifestMismatch, changed_preflight.validateAgainst(prepared));
    // Only the copied header changes; no borrowed trace or source is mutated
    // or destroyed by this constructor-ingress rejection.
    var changed_prepared = prepared.*;
    changed_prepared.format_version +%= 1;
    try std.testing.expectError(error.IdentityMismatch, subject.PreflightV2.init(&changed_prepared));
    var public_native_relations = subject.nativeRelations(prepared);
    const public_native_inputs = subject.publicInputs(
        prepared,
        &public_native_relations,
    );
    var public_native_sum_source = recursion
        .segment_public_native_sum_authority_v2.SourceV2.init(
        allocator,
        &source_preflight.public_prepared,
        public_native_inputs,
    ) catch |err| return failStage("public_native_sum_source", err);
    defer public_native_sum_source.deinit();
    var log_sizes = [_]u32{0} ** subject.UNIVERSAL_COMPONENT_COUNT;
    try source_preflight.installLogSizes(&log_sizes);
    for (
        prepared.rows_18_34_core.log_sizes,
        core_outer.NATIVE_V2_CORE_FIRST_ROW..,
    ) |log_size, row| log_sizes[row] = log_size;

    // The boundary-independent core receipt counts only its suffix. Row 34
    // commits the admitted transcript + authority prefix and the core suffix
    // as one provider, so install its complete minimal domain here.
    const complete_poseidon_calls = try std.math.add(
        usize,
        prepared.row34_boundary_prefix_calls.len,
        prepared.rows_18_34_core.core_poseidon_call_count,
    );
    log_sizes[34] = @intCast(@max(
        @as(usize, 1),
        std.math.log2_int_ceil(usize, complete_poseidon_calls),
    ));
    const manifest = manifest_mod.buildWithProviderShape(
        log_sizes,
        &source_preflight.transcript_manifest,
        &source_preflight.statement_manifest,
        &source_preflight.public_manifest,
        &source_preflight.boundary_manifest,
        source_preflight.input_provider_shape,
    ) catch |err| return failStage("manifest", err);

    var init_timer = try std.time.Timer.start();
    const owner = try allocator.create(subject.Owner);
    subject.Owner.initInPlace(
        owner,
        allocator,
        prepared,
        &manifest,
        &public_native_sum_source,
    ) catch |err| {
        allocator.destroy(owner);
        return failStage("owner_init", err);
    };
    const init_ns = init_timer.read();
    defer {
        owner.deinit();
        allocator.destroy(owner);
    }
    owner.validate() catch |err| return failStage("owner_validate", err);

    var tree0 = PublicationTree.init(
        allocator,
        &manifest,
        manifest_mod.PREPROCESSED_TREE_INDEX,
    ) catch |err| return failStage("tree0_init", err);
    defer tree0.deinit();
    var tree1 = PublicationTree.init(
        allocator,
        &manifest,
        manifest_mod.MAIN_TREE_INDEX,
    ) catch |err| return failStage("tree1_init", err);
    defer tree1.deinit();
    var tree2 = PublicationTree.init(
        allocator,
        &manifest,
        manifest_mod.INTERACTION_TREE_INDEX,
    ) catch |err| return failStage("tree2_init", err);
    defer tree2.deinit();
    var publish_01_timer = try std.time.Timer.start();
    owner.fillPreprocessedInto(&manifest, tree0.columns) catch |err|
        return failStage("tree0_fill", err);
    owner.fillMainInto(&manifest, tree1.columns) catch |err|
        return failStage("tree1_fill", err);
    const publish_01_ns = publish_01_timer.read();
    if (!containsNonZero(tree0.storage) or !containsNonZero(tree1.storage))
        return error.TreePublicationEmpty;
    if (!coreRowsAreZero(&manifest, manifest_mod.PREPROCESSED_TREE_INDEX, tree0.columns) or
        !coreRowsAreZero(&manifest, manifest_mod.MAIN_TREE_INDEX, tree1.columns))
    {
        return error.CoreTreeMutation;
    }

    // Use an actual transcript draw distinct from ingress admission. This is
    // the lifecycle check that forces boundary Tree 2 regeneration while the
    // owner itself enforces byte equality for committed Tree 0/1.
    var channel = leaf_outer.Engine.Channel{};
    channel.mixU32s(&.{ 0x4e43_5632, 1, 38, 47 });
    const relations = universal.UniversalRelations.draw(allocator, &channel) catch |err|
        return failStage("relation_draw", err);
    const provider_relations = shared_provider.SharedProviderRelations.init(
        &relations,
    ) catch |err| return failStage("provider_relations", err);
    var interaction_timer = try std.time.Timer.start();
    const generated = owner.prepareInteractions(
        allocator,
        &relations,
        &provider_relations,
    ) catch |err| return failStage("interaction_prepare", err);
    const interaction_ns = interaction_timer.read();
    try generated.validateCachedAgainst(owner, &relations, &provider_relations);
    if (std.mem.eql(
        u8,
        &owner.boundary_active_prepared.?.outer_relation_context_sha_id,
        &prepared.authority_prepared.outer_relation_context_sha_id,
    )) return error.RelationContextDidNotChange;

    var publish_2_timer = try std.time.Timer.start();
    const published = owner.fillInteractionInto(&manifest, tree2.columns) catch |err|
        return failStage("tree2_fill", err);
    const publish_2_ns = publish_2_timer.read();
    if (!std.meta.eql(generated, published) or !containsNonZero(tree2.storage))
        return error.TreePublicationEmpty;
    if (!coreRowsAreZero(
        &manifest,
        manifest_mod.INTERACTION_TREE_INDEX,
        tree2.columns,
    )) return error.CoreTreeMutation;

    // Generic engine validation is intentionally cached and allocation-free.
    // Repeating it here protects the performance contract from an accidental
    // reintroduction of the 21-row independent audit replay.
    const validation_iterations: usize = 4;
    var cached_timer = try std.time.Timer.start();
    for (0..validation_iterations) |_| try generated.validateCachedAgainst(
        owner,
        &relations,
        &provider_relations,
    );
    const cached_validation_ns = cached_timer.read();
    const cached = try owner.prepareInteractions(
        allocator,
        &relations,
        &provider_relations,
    );
    if (!std.meta.eql(generated, cached))
        return error.CachedGenerationMismatch;

    // A second challenge context is rejected before cached Tree 2, workspaces,
    // or the active pointer-free receipt can change.
    const receipt_before = owner.active_generated.?;
    const tree_before = try owner.interactionTreeIdentity();
    const admission_provider = try shared_provider.SharedProviderRelations.init(
        &prepared.outer_relations,
    );
    if (owner.prepareInteractions(
        allocator,
        &prepared.outer_relations,
        &admission_provider,
    )) |_| return error.ForeignContextAccepted else |_| {}
    if (!std.meta.eql(receipt_before, owner.active_generated.?))
        return error.InteractionCacheMutation;
    const tree_after = try owner.interactionTreeIdentity();
    if (!std.mem.eql(u8, &tree_before, &tree_after))
        return error.InteractionCacheMutation;

    std.debug.print(
        "\nV2_NONCORE_OWNER_REAL rows={d} init_ms={d:.3} " ++
            "publish_01_ms={d:.3} interaction_ms={d:.3} " ++
            "publish_2_ms={d:.3} cached_validate_ns={d} " ++
            "cached_validate_iterations={d} hot_allocations={d}/{d}/{d} " ++
            "cold_independent_audit_replays={d}\n",
        .{
            subject.OWNED_ROW_COUNT,
            milliseconds(init_ns),
            milliseconds(publish_01_ns),
            milliseconds(interaction_ns),
            milliseconds(publish_2_ns),
            cached_validation_ns,
            validation_iterations,
            subject.HOT_TREE_HEAP_ALLOCATIONS[0],
            subject.HOT_TREE_HEAP_ALLOCATIONS[1],
            subject.HOT_TREE_HEAP_ALLOCATIONS[2],
            subject.COLD_INDEPENDENT_AUDIT_REPLAYS_PER_GENERATION,
        },
    );
}

const PublicationTree = struct {
    allocator: std.mem.Allocator,
    columns: [][]M31,
    storage: []M31,

    fn init(
        allocator: std.mem.Allocator,
        manifest: *const manifest_mod.Manifest,
        tree: usize,
    ) !PublicationTree {
        const column_count: usize = switch (tree) {
            manifest_mod.PREPROCESSED_TREE_INDEX => manifest.total_preprocessed_columns,
            manifest_mod.MAIN_TREE_INDEX => manifest.total_main_columns,
            manifest_mod.INTERACTION_TREE_INDEX => manifest.total_interaction_columns,
            else => return error.InvalidTreeIndex,
        };
        const columns = try allocator.alloc([]M31, column_count);
        errdefer allocator.free(columns);
        for (columns) |*column| column.* = @constCast((&[_]M31{})[0..]);
        var words: usize = 0;
        for (manifest.roster_rows[0..manifest.roster_count]) |row| {
            const placement = manifest.placements[row].?;
            const count: usize = switch (tree) {
                manifest_mod.PREPROCESSED_TREE_INDEX => placement.geometry.preprocessed_columns,
                manifest_mod.MAIN_TREE_INDEX => placement.geometry.main_columns,
                manifest_mod.INTERACTION_TREE_INDEX => placement.geometry.interaction_columns,
                else => unreachable,
            };
            const rows = @as(usize, 1) << @intCast(placement.geometry.log_size);
            words = try std.math.add(
                usize,
                words,
                try std.math.mul(usize, count, rows),
            );
        }
        const storage = try allocator.alloc(M31, words);
        errdefer allocator.free(storage);
        @memset(storage, M31.zero());
        var cursor: usize = 0;
        for (manifest.roster_rows[0..manifest.roster_count]) |row| {
            const placement = manifest.placements[row].?;
            const offset: usize = switch (tree) {
                manifest_mod.PREPROCESSED_TREE_INDEX => placement.preprocessed_offset,
                manifest_mod.MAIN_TREE_INDEX => placement.main_offset,
                manifest_mod.INTERACTION_TREE_INDEX => placement.interaction_offset,
                else => unreachable,
            };
            const count: usize = switch (tree) {
                manifest_mod.PREPROCESSED_TREE_INDEX => placement.geometry.preprocessed_columns,
                manifest_mod.MAIN_TREE_INDEX => placement.geometry.main_columns,
                manifest_mod.INTERACTION_TREE_INDEX => placement.geometry.interaction_columns,
                else => unreachable,
            };
            const rows = @as(usize, 1) << @intCast(placement.geometry.log_size);
            for (columns[offset..][0..count]) |*column| {
                column.* = storage[cursor..][0..rows];
                cursor += rows;
            }
        }
        std.debug.assert(cursor == storage.len);
        return .{ .allocator = allocator, .columns = columns, .storage = storage };
    }

    fn deinit(self: *PublicationTree) void {
        self.allocator.free(self.storage);
        self.allocator.free(self.columns);
        self.* = undefined;
    }
};

fn containsNonZero(values: []const M31) bool {
    for (values) |value| if (!value.isZero()) return true;
    return false;
}

fn coreRowsAreZero(
    manifest: *const manifest_mod.Manifest,
    tree: usize,
    columns: []const []M31,
) bool {
    for (core_outer.NATIVE_V2_CORE_FIRST_ROW..core_outer.NATIVE_V2_CORE_LAST_ROW + 1) |row| {
        const placement = manifest.placements[row].?;
        const offset: usize = switch (tree) {
            manifest_mod.PREPROCESSED_TREE_INDEX => placement.preprocessed_offset,
            manifest_mod.MAIN_TREE_INDEX => placement.main_offset,
            manifest_mod.INTERACTION_TREE_INDEX => placement.interaction_offset,
            else => return false,
        };
        const count: usize = switch (tree) {
            manifest_mod.PREPROCESSED_TREE_INDEX => placement.geometry.preprocessed_columns,
            manifest_mod.MAIN_TREE_INDEX => placement.geometry.main_columns,
            manifest_mod.INTERACTION_TREE_INDEX => placement.geometry.interaction_columns,
            else => return false,
        };
        for (columns[offset..][0..count]) |column|
            for (column) |value| if (!value.isZero()) return false;
    }
    return true;
}

fn milliseconds(nanoseconds: u64) f64 {
    return @as(f64, @floatFromInt(nanoseconds)) / std.time.ns_per_ms;
}

fn failStage(stage: []const u8, err: anyerror) anyerror {
    std.debug.print("\nV2_NONCORE_OWNER_REAL_FAIL stage={s} error={s}\n", .{
        stage,
        @errorName(err),
    });
    return err;
}

